    50        std::vector<std::pair<sv, size_t>> keys;
    51
    52        auto read_key = [&](auto&& start, auto&& it) {
    53           sv key{start, size_t(it - start)};
    54
    55           size_t csv_index{};
    56
    57           const auto brace_pos = key.find('[');
    58           if (brace_pos != sv::npos) {
    59              const auto close_brace = key.find(']');
    60              const auto index = key.substr(brace_pos + 1, close_brace - (brace_pos + 1));
    61              key = key.substr(0, brace_pos);
    62              const auto [ptr, ec] = std::from_chars(index.data(), index.data() + index.size(), csv_index);
    63              if (ec != std::errc()) {
    64                 ctx.error = error_code::syntax_error;
    65                 return;
    66              }
    67           }
    68
    69           keys.emplace_back(std::pair{key, csv_index});
    70        };
    71
    72        auto start = it;
    73        while (it != end) {
    74           if (*it == ',') {
    75              read_key(start, it);
    76              ++it;
    77              start = it;
    78           }
    79           else if (*it == '\r' || *it == '\n') {
    80              auto line_end = it; // Position before incrementing
    81              if (*it == '\r') {
    82                 ++it;
    83                 if (it != end && *it != '\n') [[unlikely]] {
    84                    ctx.error = error_code::syntax_error;
    85                    return keys;
    86                 }
    87              }
    88
    89              if (start == line_end) {
    90                 // trailing comma or empty
    91              }
    92              else {
    93                 read_key(start, line_end); // Use original line ending position
    94              }
    95              break;
    96           }
    97           else {
    98              ++it;
    99           }
   100        }
   101
   102        return keys;
   103     }
