   105     template <readable_map_t T>
   106     struct from<CSV, T>
   107     {
   108        template <auto Opts, class It>
   109        static void op(auto&& value, is_context auto&& ctx, It&& it, auto&& end)
   110        {
   111           if constexpr (check_layout(Opts) == rowwise) {
   112              while (it != end) {
   113                 auto start = it;
   114                 goto_delim<','>(it, end);
   115                 sv key{start, static_cast<size_t>(it - start)};
   116
   117                 size_t csv_index{};
   118
   119                 const auto brace_pos = key.find('[');
   120                 if (brace_pos != sv::npos) {
   121                    const auto close_brace = key.find(']');
   122                    const auto index = key.substr(brace_pos + 1, close_brace - (brace_pos + 1));
   123                    key = key.substr(0, brace_pos);
   124                    const auto [ptr, ec] = std::from_chars(index.data(), index.data() + index.size(), csv_index);
   125                    if (ec != std::errc()) {
   126                       ctx.error = error_code::syntax_error;
   127                       return;
   128                    }
   129                 }
   130
   131                 if (it == end || *it != ',') [[unlikely]] {
   132                    ctx.error = error_code::syntax_error;
   133                    return;
   134                 }
   135                 ++it;
   136
   137                 using key_type = typename std::decay_t<decltype(value)>::key_type;
   138                 auto& member = value[key_type(key)];
   139                 using M = std::decay_t<decltype(member)>;
   140                 if constexpr (fixed_array_value_t<M> && emplace_backable<M>) {
   141                    size_t col = 0;
   142                    while (it != end) {
   143                       if (col < member.size()) [[likely]] {
   144                          parse<CSV>::op<Opts>(member[col][csv_index], ctx, it, end);
   145                       }
   146                       else [[unlikely]] {
   147                          parse<CSV>::op<Opts>(member.emplace_back()[csv_index], ctx, it, end);
   148                       }
   149
   150                       if (it == end) break;
   151
   152                       if (*it == '\r') {
   153                          ++it;
   154                          if (it != end && *it == '\n') {
   155                             ++it;
   156                          }
   157                          break;
   158                       }
   159                       else if (*it == '\n') {
   160                          ++it;
   161                          break;
   162                       }
   163
   164                       if (*it == ',') {
   165                          ++it;
   166                       }
   167                       else {
   168                          ctx.error = error_code::syntax_error;
   169                          return;
   170                       }
   171
   172                       ++col;
   173                    }
   174                 }
   175                 else {
   176                    while (it != end) {
   177                       parse<CSV>::op<Opts>(member, ctx, it, end);
   178
   179                       if (it == end) break;
   180
   181                       if (*it == '\r') {
   182                          ++it;
   183                          if (it != end && *it == '\n') {
   184                             ++it;
   185                          }
   186                          break;
   187                       }
   188                       else if (*it == '\n') {
   189                          ++it;
   190                          break;
   191                       }
   192
   193                       if (*it == ',') {
   194                          ++it;
   195                       }
   196                       else {
   197                          ctx.error = error_code::syntax_error;
   198                          return;
   199                       }
   200                    }
   201                 }
   202              }
   203           }
   204           else // column wise
   205           {
   206              const auto keys = read_column_wise_keys(ctx, it, end);
   207
   208              if (bool(ctx.error)) {
   209                 return;
   210              }
   211
   212              if (csv_new_line(ctx, it, end)) {
   213                 return;
   214              }
   215
   216              const auto n_keys = keys.size();
   217
   218              size_t row = 0;
   219
   220              while (it != end) {
   221                 for (size_t i = 0; i < n_keys; ++i) {
   222                    using key_type = typename std::decay_t<decltype(value)>::key_type;
   223                    auto& member = value[key_type(keys[i].first)];
   224                    using M = std::decay_t<decltype(member)>;
   225                    if constexpr (fixed_array_value_t<M> && emplace_backable<M>) {
   226                       const auto index = keys[i].second;
   227                       if (row < member.size()) [[likely]] {
   228                          parse<CSV>::op<Opts>(member[row][index], ctx, it, end);
   229                       }
   230                       else [[unlikely]] {
   231                          parse<CSV>::op<Opts>(member.emplace_back()[index], ctx, it, end);
   232                       }
   233                    }
   234                    else {
   235                       parse<CSV>::op<Opts>(member, ctx, it, end);
   236                    }
   237
   238                    if (it != end && *it == ',') {
   239                       ++it;
   240                    }
   241                 }
   242
   243                 if (it == end) break;
   244
   245                 if (*it == '\r') {
   246                    ++it;
   247                    if (it != end && *it == '\n') {
   248                       ++it;
   249                       ++row;
   250                    }
   251                    else [[unlikely]] {
   252                       ctx.error = error_code::syntax_error;
   253                       return;
   254                    }
   255                 }
   256                 else if (*it == '\n') {
   257                    ++it;
   258                    ++row;
   259                 }
   260              }
   261           }
   262        }
